import { createStateMachine } from './state-machine'
import type { StateMachine } from './types'

/**
 * 活动订单状态枚举
 */
export type ActivityState =
  | 'pending_payment'
  | 'paid'
  | 'completed'
  | 'cancelled'
  | 'refunded'

/** 状态转移表 */
export type ActivityTransitions = Record<ActivityState, ActivityState[]>

/**
 * 活动订单状态机
 *   - pending_payment → paid / cancelled
 *   - paid            → completed / refunded
 *   - completed / cancelled / refunded 为终态
 */
export const activityOrderStateMachine: StateMachine<ActivityState> & {
  initial: ActivityState
  states: ActivityState[]
  transitions: ActivityTransitions
  isValidState: (s: string) => s is ActivityState
  nextStates: (from: ActivityState) => ActivityState[]
  isTerminal: (state: ActivityState) => boolean
  getMetadata: (state: ActivityState) => Record<string, unknown> | null
} = createStateMachine<ActivityState>({
  initial: 'pending_payment',
  states: ['pending_payment', 'paid', 'completed', 'cancelled', 'refunded'],
  transitions: {
    pending_payment: ['paid', 'cancelled'],
    paid: ['completed', 'refunded'],
    completed: [],
    cancelled: [],
    refunded: [],
  },
})